(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit31-trap-c6-advanced-1"]={"id":"unit31-trap-c6-advanced-1","unitId":"3-1","chapterIds":["3-1"],"unitType":"advanced","group":"3-1단원 · 선지 변형 유형 · 주체","name":"심화 1","level":"심화","revision":1,"originPage":"unit31","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"주체","parts":[{"name":"U31-P02-02-S1 · 주체","items":[{"paragraphCount":1,"readingLabel":"2문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 2문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 2문단]\n사랑은 또한 위험한 것이기도 하다. 많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다. 부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다. 연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다. 그 결과 우리는 사랑을 통해서 서로 성숙하고 함께 행복하기보다는 사랑으로 인해 힘들어하고 슬픔과 좌절에 빠지는 경우가 많다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["주체"],"why":"이 사례에서 부모는 자녀의 적성이나 개성, 소망을 고려하지 않는다. 자녀에게 부모 자신의 욕심을 강요한다.\n근거: “부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다.”\n2문단에서 확인할 수 있어요.","evidence":{"title":"부모가 자기 욕망을 강요한다.","statement":"부모는 자녀가 원하는 것을 무시하고 자신이 원하는 것을 강요한다.","explanation":"이 사례에서 부모는 자녀의 적성이나 개성, 소망을 고려하지 않는다. 자녀에게 부모 자신의 욕심을 강요한다.\n근거: “부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다.”\n2문단에서 확인할 수 있어요.","valid":["R02:3"],"sources":[{"id":"R02","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"2문단","sentences":[{"id":"R02:1","text":"사랑은 또한 위험한 것이기도 하다.","paragraph":0,"memberIds":["R02:1"],"topic":"게다가 사랑은 위험한 것이기도 하다."},{"id":"R02:2","text":"많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다.","paragraph":0,"memberIds":["R02:2"],"topic":"성숙한 사랑은 상대만의 개성과 됨됨이(인격)를 존중한다. 그런데 많은 사랑은 그런 모습이 아니다. 사실은 상대를 통해 내 욕심(욕망)을 이루려고 매달리는 집착의 모습이다."},{"id":"R02:3","text":"부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다.","paragraph":0,"memberIds":["R02:3"],"topic":"부모는 자녀가 무엇을 잘하는지(적성), 어떤 사람인지(개성), 무엇을 바라는지(소망)를 생각하지 않고, 자기가 바라는 것을 자녀에게 억지로 시키곤 한다."},{"id":"R02:4","text":"연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다.","paragraph":0,"memberIds":["R02:4"],"topic":"연인을 사랑할 때도 연인을 내 것으로 갖고(소유) 내 마음대로 하고 싶은(지배) 욕심이 끼어들기(개입되기) 쉽다."},{"id":"R02:5","text":"그 결과 우리는 사랑을 통해서 서로 성숙하고 함께 행복하기보다는 사랑으로 인해 힘들어하고 슬픔과 좌절에 빠지는 경우가 많다.","paragraph":0,"memberIds":["R02:5"],"topic":"그래서 우리는 사랑으로 서로 자라고(성숙하고) 함께 행복해지기보다, 사랑 때문에 힘들어하고 슬퍼하고 좌절하는 경우가 많다."}]}]},"id":"U31-P02-02-S1","type":"mc","sent":"2문단의 내용과 맞는 설명은?","options":["부모는 자신이 원하는 것을 버리고 자녀가 원하는 것을 존중한다.","많은 사람은 상대를 사랑할 때 자기 욕심을 전혀 채우려 하지 않는다.","연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심은 생길 수 없다.","상대에게 집착하면 사랑 때문에 행복해하고 만족하는 경우가 많다.","부모는 자녀가 원하는 것을 무시하고 자신이 원하는 것을 강요한다."],"answer":"부모는 자녀가 원하는 것을 무시하고 자신이 원하는 것을 강요한다.","choiceReviews":{"부모는 자녀가 원하는 것을 무시하고 자신이 원하는 것을 강요한다.":{"reason":"이 사례에서 부모는 자녀의 적성이나 개성, 소망을 고려하지 않는다. 자녀에게 부모 자신의 욕심을 강요한다.\n근거: “부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다.”\n2문단에서 확인할 수 있어요.","edits":[]},"부모는 자신이 원하는 것을 버리고 자녀가 원하는 것을 존중한다.":{"reason":"바르게 고치면: 부모는 자녀가 원하는 것을 무시하고 자신이 원하는 것을 강요한다.\n이 사례에서 부모는 자녀의 적성이나 개성, 소망을 고려하지 않는다. 자녀에게 부모 자신의 욕심을 강요한다.\n근거: “부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":0,"end":4,"before":"부모는 ","after":"부모는 자녀가 원하는 것을 무시하고 "},{"start":15,"end":35,"before":"버리고 자녀가 원하는 것을 존중한다.","after":"강요한다."}]},"많은 사람은 상대를 사랑할 때 자기 욕심을 전혀 채우려 하지 않는다.":{"reason":"바르게 고치면: 많은 사람은 상대를 사랑한다면서 자기 욕심을 채우려 한다.\n글쓴이는 상대를 존중하는 사랑과 자기 욕심을 채우려는 집착을 다르게 본다. 상대를 통해 자기 뜻만 이루려 한다면 집착이다.\n근거: “많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":11,"end":17,"before":"사랑할 때 ","after":"사랑한다면서 "},{"start":24,"end":27,"before":"전혀 ","after":""},{"start":31,"end":38,"before":"하지 않는다.","after":"한다."}]},"연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심은 생길 수 없다.":{"reason":"바르게 고치면: 연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.\n연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.\n근거: “연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":28,"end":40,"before":"욕심은 생길 수 없다.","after":"욕심이 생기기 쉽다."}]},"상대에게 집착하면 사랑 때문에 행복해하고 만족하는 경우가 많다.":{"reason":"바르게 고치면: 상대에게 집착하면 사랑 때문에 힘들어하고 좌절하는 경우가 많다.\n상대에게 집착하면 사랑 때문에 힘들어하고 좌절하는 경우가 많다.\n근거: “그 결과 우리는 사랑을 통해서 서로 성숙하고 함께 행복하기보다는 사랑으로 인해 힘들어하고 슬픔과 좌절에 빠지는 경우가 많다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":17,"end":28,"before":"행복해하고 만족하는 ","after":"힘들어하고 좌절하는 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"c02c70c5a60f2f686aee445ac53b29c28a10ffc768c6f860a225e0dc04511609"}]},{"name":"U31-P03-03-S1 · 주체","items":[{"paragraphCount":1,"readingLabel":"3문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 3문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 3문단]\n그럼에도 우리는 사랑이란 진지하게 탐구할 필요가 없을 정도로 자명한 현상이라고 생각한다. 그리고 사랑하는 방법도 이미 잘 알고 있어서 배울 필요가 없다고 생각한다. 우리는 과연 사랑에 대해서 잘 알고 있는가?","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["주체"],"why":"글쓴이는 마지막에 '우리가 사랑을 정말 잘 알고 있을까?'라고 묻는다.\n근거: “우리는 과연 사랑에 대해서 잘 알고 있는가?”\n3문단에서 확인할 수 있어요.","evidence":{"title":"끝의 질문은 앎을 되묻는다.","statement":"글쓴이는 마지막에 '우리가 사랑을 정말 잘 알고 있을까?'라고 묻는다.","explanation":"글쓴이는 마지막에 '우리가 사랑을 정말 잘 알고 있을까?'라고 묻는다.\n근거: “우리는 과연 사랑에 대해서 잘 알고 있는가?”\n3문단에서 확인할 수 있어요.","valid":["R03:3"],"sources":[{"id":"R03","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"3문단","sentences":[{"id":"R03:1","text":"그럼에도 우리는 사랑이란 진지하게 탐구할 필요가 없을 정도로 자명한 현상이라고 생각한다.","paragraph":0,"memberIds":["R03:1"],"topic":"그런데도 우리는 사랑을 '너무 뻔한 것(자명한 현상)'이라고 생각한다. 진지하게 파고들(탐구할) 필요도 없다고 여긴다."},{"id":"R03:2","text":"그리고 사랑하는 방법도 이미 잘 알고 있어서 배울 필요가 없다고 생각한다.","paragraph":0,"memberIds":["R03:2"],"topic":"그리고 사랑하는 방법도 이미 잘 알고 있으니 배울 필요가 없다고 생각한다."},{"id":"R03:3","text":"우리는 과연 사랑에 대해서 잘 알고 있는가?","paragraph":0,"memberIds":["R03:3"],"topic":"그런데 우리는 정말 사랑에 대해 잘 알고 있을까?"}]}]},"id":"U31-P03-03-S1","type":"mc","sent":"3문단의 내용과 맞는 설명은?","options":["글쓴이는 마지막에 '우리는 사랑을 정말 잘 알고 있다'고 확신한다.","사람들은 사랑을 낯설게 느낀다. 그래서 깊이 알아보아야 한다고 여긴다.","글쓴이는 마지막에 '우리가 사랑을 정말 잘 알고 있을까?'라고 묻는다.","사람들은 사랑하는 방법을 전혀 모른다고 생각한다. 그래서 반드시 새로 배워야 한다고 여긴다.","사람들은 사랑을 너무 복잡한 일로 여겨 자세히 알아봐야만 이해할 수 있다고 생각한다."],"answer":"글쓴이는 마지막에 '우리가 사랑을 정말 잘 알고 있을까?'라고 묻는다.","choiceReviews":{"글쓴이는 마지막에 '우리가 사랑을 정말 잘 알고 있을까?'라고 묻는다.":{"reason":"글쓴이는 마지막에 '우리가 사랑을 정말 잘 알고 있을까?'라고 묻는다.\n근거: “우리는 과연 사랑에 대해서 잘 알고 있는가?”\n3문단에서 확인할 수 있어요.","edits":[]},"글쓴이는 마지막에 '우리는 사랑을 정말 잘 알고 있다'고 확신한다.":{"reason":"바르게 고치면: 글쓴이는 마지막에 '우리가 사랑을 정말 잘 알고 있을까?'라고 묻는다.\n글쓴이는 마지막에 '우리가 사랑을 정말 잘 알고 있을까?'라고 묻는다.\n근거: “우리는 과연 사랑에 대해서 잘 알고 있는가?”\n3문단에서 확인할 수 있어요.","edits":[{"start":10,"end":15,"before":"'우리는 ","after":"'우리가 "},{"start":27,"end":37,"before":"있다'고 확신한다.","after":"있을까?'라고 묻는다."}]},"사람들은 사랑을 낯설게 느낀다. 그래서 깊이 알아보아야 한다고 여긴다.":{"reason":"바르게 고치면: 사람들은 사랑을 이미 잘 안다고 생각한다. 그래서 깊이 알아볼 필요도 없다고 여긴다.\n사람들은 사랑을 이미 잘 안다고 생각한다. 그래서 깊이 알아볼 필요도 없다고 여긴다.\n근거: “그럼에도 우리는 사랑이란 진지하게 탐구할 필요가 없을 정도로 자명한 현상이라고 생각한다.”\n3문단에서 확인할 수 있어요.","edits":[{"start":9,"end":18,"before":"낯설게 느낀다. ","after":"이미 잘 안다고 생각한다. "},{"start":25,"end":35,"before":"알아보아야 한다고 ","after":"알아볼 필요도 없다고 "}]},"사람들은 사랑하는 방법을 전혀 모른다고 생각한다. 그래서 반드시 새로 배워야 한다고 여긴다.":{"reason":"바르게 고치면: 사람들은 사랑하는 방법을 이미 잘 안다고 생각한다. 그래서 따로 배울 필요가 없다고 여긴다.\n사람들은 사랑하는 방법을 이미 잘 안다고 생각한다. 그래서 따로 배울 필요가 없다고 여긴다.\n근거: “그리고 사랑하는 방법도 이미 잘 알고 있어서 배울 필요가 없다고 생각한다.”\n3문단에서 확인할 수 있어요.","edits":[{"start":14,"end":22,"before":"전혀 모른다고 ","after":"이미 잘 안다고 "},{"start":32,"end":47,"before":"반드시 새로 배워야 한다고 ","after":"따로 배울 필요가 없다고 "}]},"사람들은 사랑을 너무 복잡한 일로 여겨 자세히 알아봐야만 이해할 수 있다고 생각한다.":{"reason":"바르게 고치면: 사람들은 사랑을 너무 당연한 일로 여겨 자세히 알아볼 필요가 없다고 생각한다.\n이 문단의 '자명하다'는 너무 당연하고 분명하다는 뜻이다. 사람들은 사랑을 이미 잘 안다고 생각한다.\n근거: “그럼에도 우리는 사랑이란 진지하게 탐구할 필요가 없을 정도로 자명한 현상이라고 생각한다.”\n3문단에서 확인할 수 있어요.","edits":[{"start":12,"end":16,"before":"복잡한 ","after":"당연한 "},{"start":26,"end":42,"before":"알아봐야만 이해할 수 있다고 ","after":"알아볼 필요가 없다고 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"aaaf12c5762f59ed66920bdf272afcb2e515b0750aff5aaa7e17633aa7d6fb83"}]},{"name":"U31-P05-01-S1 · 주체","items":[{"paragraphCount":1,"readingLabel":"5문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 5문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 5문단]\n첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다. 따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다. 사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["주체"],"why":"현대인은 '어떻게 사랑할까'보다 '어떻게 사랑받을까'를 고민한다.\n근거: “첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.”\n5문단에서 확인할 수 있어요.","evidence":{"title":"현대인은 사랑받는 데 집중한다.","statement":"현대인은 '어떻게 사랑할까'보다 '어떻게 사랑받을까'를 고민한다.","explanation":"현대인은 '어떻게 사랑할까'보다 '어떻게 사랑받을까'를 고민한다.\n근거: “첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.”\n5문단에서 확인할 수 있어요.","valid":["R05:1"],"sources":[{"id":"R05","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"5문단","sentences":[{"id":"R05:1","text":"첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.","paragraph":0,"memberIds":["R05:1"],"topic":"첫째, 현대인은 연인 사이의 사랑을 '내가 상대를 어떻게 사랑할까'의 문제로 보지 않는다. '멋진 사람에게 어떻게 하면 사랑받을까'의 문제로 본다."},{"id":"R05:2","text":"따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.","paragraph":0,"memberIds":["R05:2"],"topic":"그래서 현대인은 사랑받을 만한 사람이 되려고, 다시 말해 최대한 매력 있어 보이려고 온갖 노력을 다한다."},{"id":"R05:3","text":"사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.","paragraph":0,"memberIds":["R05:3"],"topic":"매력 있어 보이려고 사람들이 주로 쓰는 방법은 이렇다. 부자가 되거나 높은 자리(고위직)에 오르기, 아름다운 외모 갖기, 유머를 쓰고 대화를 재미있게 이끌기, 모나지 않게 모두와 사이좋게 지내기."}]}]},"id":"U31-P05-01-S1","type":"mc","sent":"5문단의 내용과 맞는 설명은?","options":["현대인은 '어떻게 사랑받을까'보다 '어떻게 사랑할까'를 고민한다.","현대인은 사랑받으려고 자신을 최대한 매력 없게 꾸민다.","사람들은 매력적으로 보이려 해도 부자가 되거나 높은 지위에 오르려 하지는 않는다.","사람들은 매력적으로 보이려 해도 유머를 쓰거나 재미있게 대화하지는 않는다.","현대인은 '어떻게 사랑할까'보다 '어떻게 사랑받을까'를 고민한다."],"answer":"현대인은 '어떻게 사랑할까'보다 '어떻게 사랑받을까'를 고민한다.","choiceReviews":{"현대인은 '어떻게 사랑할까'보다 '어떻게 사랑받을까'를 고민한다.":{"reason":"현대인은 '어떻게 사랑할까'보다 '어떻게 사랑받을까'를 고민한다.\n근거: “첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.”\n5문단에서 확인할 수 있어요.","edits":[]},"현대인은 '어떻게 사랑받을까'보다 '어떻게 사랑할까'를 고민한다.":{"reason":"바르게 고치면: 현대인은 '어떻게 사랑할까'보다 '어떻게 사랑받을까'를 고민한다.\n현대인은 '어떻게 사랑할까'보다 '어떻게 사랑받을까'를 고민한다.\n근거: “첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.”\n5문단에서 확인할 수 있어요.","edits":[{"start":10,"end":19,"before":"사랑받을까'보다 ","after":"사랑할까'보다 "},{"start":24,"end":31,"before":"사랑할까'를 ","after":"사랑받을까'를 "}]},"현대인은 사랑받으려고 자신을 최대한 매력 없게 꾸민다.":{"reason":"바르게 고치면: 현대인은 사랑받으려고 자신을 최대한 매력적으로 꾸민다.\n현대인은 사랑받으려고 자신을 최대한 매력적으로 꾸민다.\n근거: “따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.”\n5문단에서 확인할 수 있어요.","edits":[{"start":20,"end":26,"before":"매력 없게 ","after":"매력적으로 "}]},"사람들은 매력적으로 보이려 해도 부자가 되거나 높은 지위에 오르려 하지는 않는다.":{"reason":"바르게 고치면: 사람들은 매력적으로 보이려고 부자가 되거나 높은 지위에 오르려 한다.\n사람들은 매력적으로 보이려고 부자가 되거나 높은 지위에 오르려 한다.\n근거: “사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.”\n5문단에서 확인할 수 있어요.","edits":[{"start":11,"end":18,"before":"보이려 해도 ","after":"보이려고 "},{"start":37,"end":45,"before":"하지는 않는다.","after":"한다."}]},"사람들은 매력적으로 보이려 해도 유머를 쓰거나 재미있게 대화하지는 않는다.":{"reason":"바르게 고치면: 사람들은 매력적으로 보이려고 유머를 쓰고 재미있게 대화한다.\n사람들은 매력적으로 보이려고 유머를 쓰고 재미있게 대화한다.\n근거: “사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.”\n5문단에서 확인할 수 있어요.","edits":[{"start":11,"end":18,"before":"보이려 해도 ","after":"보이려고 "},{"start":22,"end":26,"before":"쓰거나 ","after":"쓰고 "},{"start":31,"end":41,"before":"대화하지는 않는다.","after":"대화한다."}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"e5cd96d44b2c4ff8660b7d47e20f8f81b51c0edf2723181461d44677de2b9066"}]},{"name":"U31-P07-02-S1 · 주체","items":[{"paragraphCount":1,"readingLabel":"7문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 7문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 7문단]\n프롬은 현대인의 이러한 태도가 20세기 후반에 일어난 결혼 제도의 큰 변화와 결부되어 있다고 본다. 과거 19세기나 20세기 전반까지만 해도 연인이 서로 사랑해서 결혼하지는 않았다. 결혼은 부부가 될 사람들의 부모에 의해서 이루어졌다. 이러한 혼인 제도가 지배하는 상황에서 사람들은 사랑이란 결혼의 조건이 아니고 결혼 후에 가꾸어 가는 것으로 생각했다. 그러나 20세기 후반부터는 연인이 서로 사랑에 빠져서 결혼해야 한다는 ‘낭만적인 사랑’의 관념이 지배하게 되었다. 이와 함께 사람들은 사랑을 가꾸어 가는 것보다는 사랑에 빠질 상대를 만나는 것이 가장 중요하다고 생각하게 되었다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["주체"],"why":"19세기나 20세기 전반에는 부모가 자녀의 결혼을 정했다.\n근거: “결혼은 부부가 될 사람들의 부모에 의해서 이루어졌다.”\n7문단에서 확인할 수 있어요.","evidence":{"title":"과거에는 부모가 결혼을 정했다.","statement":"19세기나 20세기 전반에는 부모가 자녀의 결혼을 정했다.","explanation":"19세기나 20세기 전반에는 부모가 자녀의 결혼을 정했다.\n근거: “결혼은 부부가 될 사람들의 부모에 의해서 이루어졌다.”\n7문단에서 확인할 수 있어요.","valid":["R07:3"],"sources":[{"id":"R07","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"7문단","sentences":[{"id":"R07:1","text":"프롬은 현대인의 이러한 태도가 20세기 후반에 일어난 결혼 제도의 큰 변화와 결부되어 있다고 본다.","paragraph":0,"memberIds":["R07:1"],"topic":"프롬은 현대인의 이런 태도가 20세기 후반에 결혼 제도가 크게 바뀐 것과 이어져(결부되어) 있다고 본다."},{"id":"R07:2","text":"과거 19세기나 20세기 전반까지만 해도 연인이 서로 사랑해서 결혼하지는 않았다.","paragraph":0,"memberIds":["R07:2"],"topic":"예전(19세기나 20세기 전반)까지만 해도 두 사람이 서로 사랑해서 결혼하지는 않았다."},{"id":"R07:3","text":"결혼은 부부가 될 사람들의 부모에 의해서 이루어졌다.","paragraph":0,"memberIds":["R07:3"],"topic":"결혼은 부부가 될 사람들의 부모가 정했다."},{"id":"R07:4","text":"이러한 혼인 제도가 지배하는 상황에서 사람들은 사랑이란 결혼의 조건이 아니고 결혼 후에 가꾸어 가는 것으로 생각했다.","paragraph":0,"memberIds":["R07:4"],"topic":"이런 결혼 방식이 당연하던 때에는, 사랑을 결혼하기 위한 조건으로 보지 않았다. 결혼한 뒤에 가꾸어 가는 것이라고 생각했다."},{"id":"R07:5","text":"그러나 20세기 후반부터는 연인이 서로 사랑에 빠져서 결혼해야 한다는 ‘낭만적인 사랑’의 관념이 지배하게 되었다.","paragraph":0,"memberIds":["R07:5"],"topic":"그런데 20세기 후반부터는 '서로 사랑에 빠져서 결혼해야 한다'는 생각, 곧 '낭만적인 사랑'이라는 생각(관념)이 당연한 것이 되었다(지배하게 되었다)."},{"id":"R07:6","text":"이와 함께 사람들은 사랑을 가꾸어 가는 것보다는 사랑에 빠질 상대를 만나는 것이 가장 중요하다고 생각하게 되었다.","paragraph":0,"memberIds":["R07:6"],"topic":"그러면서 사람들은 사랑을 가꾸어 가는 것보다, 사랑에 빠질 상대를 만나는 것이 가장 중요하다고 생각하게 되었다."}]}]},"id":"U31-P07-02-S1","type":"mc","sent":"7문단의 내용과 맞는 설명은?","options":["19세기나 20세기 전반에는 부모가 아니라 연인들 스스로 결혼을 정했다.","프롬은 현대인이 사랑을 생각하는 방식이 20세기 후반의 결혼 제도 변화와 관련 없다고 본다.","부모가 결혼을 정하던 때에는 먼저 사랑에 빠져야 결혼할 수 있다고 생각했다.","20세기 후반에는 '서로의 사랑보다 부모의 결정에 따라 결혼해야 한다'는 생각이 널리 퍼졌다.","19세기나 20세기 전반에는 부모가 자녀의 결혼을 정했다."],"answer":"19세기나 20세기 전반에는 부모가 자녀의 결혼을 정했다.","choiceReviews":{"19세기나 20세기 전반에는 부모가 자녀의 결혼을 정했다.":{"reason":"19세기나 20세기 전반에는 부모가 자녀의 결혼을 정했다.\n근거: “결혼은 부부가 될 사람들의 부모에 의해서 이루어졌다.”\n7문단에서 확인할 수 있어요.","edits":[]},"19세기나 20세기 전반에는 부모가 아니라 연인들 스스로 결혼을 정했다.":{"reason":"바르게 고치면: 19세기나 20세기 전반에는 부모가 자녀의 결혼을 정했다.\n19세기나 20세기 전반에는 부모가 자녀의 결혼을 정했다.\n근거: “결혼은 부부가 될 사람들의 부모에 의해서 이루어졌다.”\n7문단에서 확인할 수 있어요.","edits":[{"start":20,"end":32,"before":"아니라 연인들 스스로 ","after":"자녀의 "}]},"프롬은 현대인이 사랑을 생각하는 방식이 20세기 후반의 결혼 제도 변화와 관련 없다고 본다.":{"reason":"바르게 고치면: 프롬은 현대인이 사랑을 생각하는 방식이 20세기 후반의 결혼 제도 변화와 관련 있다고 본다.\n프롬은 현대인이 사랑을 생각하는 방식이 20세기 후반의 결혼 제도 변화와 관련 있다고 본다.\n근거: “프롬은 현대인의 이러한 태도가 20세기 후반에 일어난 결혼 제도의 큰 변화와 결부되어 있다고 본다.”\n7문단에서 확인할 수 있어요.","edits":[{"start":44,"end":48,"before":"없다고 ","after":"있다고 "}]},"부모가 결혼을 정하던 때에는 먼저 사랑에 빠져야 결혼할 수 있다고 생각했다.":{"reason":"바르게 고치면: 부모가 결혼을 정하던 때에는 결혼한 뒤에 사랑을 가꾸면 된다고 생각했다.\n부모가 결혼을 정하던 때에는 결혼한 뒤에 사랑을 가꾸면 된다고 생각했다.\n근거: “이러한 혼인 제도가 지배하는 상황에서 사람들은 사랑이란 결혼의 조건이 아니고 결혼 후에 가꾸어 가는 것으로 생각했다.”\n7문단에서 확인할 수 있어요.","edits":[{"start":16,"end":37,"before":"먼저 사랑에 빠져야 결혼할 수 있다고 ","after":"결혼한 뒤에 사랑을 가꾸면 된다고 "}]},"20세기 후반에는 '서로의 사랑보다 부모의 결정에 따라 결혼해야 한다'는 생각이 널리 퍼졌다.":{"reason":"바르게 고치면: 20세기 후반에는 '서로 사랑에 빠져서 결혼해야 한다'는 생각이 널리 퍼졌다.\n20세기 후반에는 '서로 사랑에 빠져서 결혼해야 한다'는 생각이 널리 퍼졌다.\n근거: “그러나 20세기 후반부터는 연인이 서로 사랑에 빠져서 결혼해야 한다는 ‘낭만적인 사랑’의 관념이 지배하게 되었다.”\n7문단에서 확인할 수 있어요.","edits":[{"start":10,"end":31,"before":"'서로의 사랑보다 부모의 결정에 따라 ","after":"'서로 사랑에 빠져서 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"176f51a7c266e754b7b6d447978f91ace4a572002e3666ff52aa52f0281c6b8a"}]}]};})(window);
